alter table public.invoices add column if not exists due_at timestamptz, add column if not exists last_collection_at timestamptz, add column if not exists collection_status text not null default 'current' check(collection_status in ('current','reminder_due','contacted','promise_to_pay','disputed','collections','paid')); create index if not exists idx_invoices_collection on public.invoices(collection_status,due_at) where status='open'; create table if not exists public.payment_requests(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,provider text not null default 'unconfigured',status text not null default 'draft' check(status in ('draft','ready','sent','paid','expired','canceled')),amount numeric(12,2) not null check(amount>0),external_reference text,checkout_url text,expires_at timestamptz,created_by uuid references public.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists idx_payment_requests_invoice on public.payment_requests(invoice_id,status); alter table public.payment_requests enable row level security; revoke all on public.payment_requests from anon; create policy payment_requests_read on public.payment_requests for select to authenticated using(public.has_permission_for_current_user('view_billing')); create or replace function private.billing_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('view_billing') then raise exception 'Billing permission required'; end if; return jsonb_build_object('openInvoices',(select count(*) from public.invoices where status='open'),'openBalance',(select coalesce(sum(greatest(i.total-coalesce((select sum(p.amount) from public.payments p where p.invoice_id=i.id),0),0)),0) from public.invoices i where i.status='open'),'pastDue',(select count(*) from public.invoices where status='open' and due_at is not null and due_at<now()),'pastDueBalance',(select coalesce(sum(greatest(i.total-coalesce((select sum(p.amount) from public.payments p where p.invoice_id=i.id),0),0)),0) from public.invoices i where i.status='open' and i.due_at is not null and i.due_at<now()),'paymentRequests',(select count(*) from public.payment_requests where status in ('ready','sent'))); end $$; create or replace function public.billing_dashboard() returns jsonb language sql stable set search_path='' as $$ select private.billing_dashboard() $$; revoke all on function public.billing_dashboard() from public,anon; grant execute on function public.billing_dashboard() to authenticated;